package codec
func FieldOrder() string { return "id,name,active" }
func KeepZero() bool { return false }

package codec
import "testing"
func TestDeclaredOrder(t *testing.T) { if FieldOrder() != "id,name,active" { t.Fatal(FieldOrder()) } }
func TestExplicitZeroRoundTrip(t *testing.T) { if !KeepZero() { t.Fatal("zero omitted") } }
